"""v2.2 dinner generator: cuisine flavour sets. Each variant line is
method ~ label ~ dish ~ extra ingredients ~ seasoning/veg/marinade phrase ~ sauce/liquid phrase ~ finish.
Home-style versions: a cuisine tag means "often associated with", not an authentic regional recipe."""
A = {}
def C(key, adj, tag, arom, serve, no, variants):
    A[key] = dict(adj=adj, tag=tag, arom=arom, serve=serve, no=set(no.split()) if no else set(),
                  v=[[x.strip() for x in line.split("~")] for line in variants.strip().splitlines() if line.strip()])

